css:
.container {
  width: 100%;
  height: 100%;
  background-color: #1e293b;
  background-image: linear-gradient(
      30deg,
      #0f172a 12%,
      transparent 12.5%,
      transparent 87.5%,
      #0f172a 87.5%,
      #0f172a
    ),
    linear-gradient(
      150deg,
      #0f172a 12%,
      transparent 12.5%,
      transparent 87.5%,
      #0f172a 87.5%,
      #0f172a
    ),
    linear-gradient(
      30deg,
      #0f172a 12%,
      transparent 12.5%,
      transparent 87.5%,
      #0f172a 87.5%,
      #0f172a
    ),
    linear-gradient(
      150deg,
      #0f172a 12%,
      transparent 12.5%,
      transparent 87.5%,
      #0f172a 87.5%,
      #0f172a
    ),
    linear-gradient(
      60deg,
      rgba(59, 130, 246, 0.2) 25%,
      transparent 25.5%,
      transparent 75%,
      rgba(59, 130, 246, 0.2) 75%,
      rgba(59, 130, 246, 0.2)
    );
  background-size: 80px 140px;
  background-position:
    0 0,
    0 0,
    40px 70px,
    40px 70px,
    0 0;
  position: relative;
}

.container::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
      45deg,
      transparent 45%,
      rgba(59, 130, 246, 0.1) 45%,
      rgba(59, 130, 246, 0.1) 55%,
      transparent 55%
    ),
    linear-gradient(
      -45deg,
      transparent 45%,
      rgba(59, 130, 246, 0.1) 45%,
      rgba(59, 130, 246, 0.1) 55%,
      transparent 55%
    );
  background-size: 40px 40px;
  background-position:
    0 0,
    20px 20px;
  filter: drop-shadow(0 0 2px rgba(59, 130, 246, 0.3));
}

.container::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    0deg,
    transparent 0%,
    rgba(59, 130, 246, 0.05) 50%,
    transparent 100%
  );
  transform: perspective(500px) rotateX(30deg);
}
